                                                (settings?.licenseCategories || []).forEach((cat: any) => {
                                                    const parent = cat.parentCategory || 'Driving';
                                                    if (!grouped[parent]) grouped[parent] = [];
                                                    grouped[parent].push(cat);
                                                });
