                                                                                        const payload = { ...settings, id: settings?.id || `ds_settings_${currentInstitution?.id}`, institutionId: currentInstitution?.id || 'inst', votes: updated };
                                                                                        await onUpdateSettings(payload);
                                                                                        success("Fee vote removed successfully.");
