                                e.preventDefault();
                                const reasonInput = (e.currentTarget.elements.namedItem('reason') as HTMLTextAreaElement).value;
                                if (!reasonInput.trim()) return;
                                if (reasonModal.onSubmit) {
                                    await reasonModal.onSubmit(reasonInput.trim());
                                }
